const listActiveControlsForPortfolio = `-- name: ListActiveControlsForPortfolio :many
WITH matched_controls AS (
    SELECT c.id, c.scf_anchor_id, c.title, c.control_family, c.bundle_id, c.evidence_queries
    FROM controls c
    WHERE c.tenant_id = $1
      AND c.superseded_by IS NULL
      AND ($3::text IS NULL OR c.control_family = $3::text)
      AND (
            $4::uuid[] IS NULL
            OR c.scf_anchor_id = ANY($4::uuid[])
          )
),
ranked_controls AS (
    SELECT
        c.id,
        c.scf_anchor_id,
        c.title,
        c.control_family,
        c.bundle_id,
        count(e.id)::bigint AS evidence_count,
        count(e.id) FILTER (WHERE e.result = 'fail')::bigint AS failing_evidence_count,
        max(e.observed_at)::timestamptz AS latest_observed_at,
        COALESCE(ef.is_stale, false)::bool AS is_stale
    FROM matched_controls c
    LEFT JOIN evidence_records e
        ON e.tenant_id = $1
       AND (e.control_id = c.id OR e.control_ref = c.id::text
           OR (e.control_id IS NULL
               AND e.evidence_kind = ANY($5::text[])
               AND c.evidence_queries @> jsonb_build_array(
                     jsonb_build_object('evidence_kind', e.evidence_kind))))
    LEFT JOIN evidence_freshness ef
        ON ef.tenant_id = $1
       AND ef.control_id = c.id
    GROUP BY c.id, c.scf_anchor_id, c.title, c.control_family, c.bundle_id, ef.is_stale
)
SELECT
    id,
    scf_anchor_id,
    title,
    control_family,
    (
        CASE WHEN evidence_count = 0 THEN 10000 ELSE 0 END +
        CASE WHEN failing_evidence_count > 0 THEN 1000 ELSE 0 END +
        CASE WHEN is_stale THEN 100 ELSE 0 END +
        LEAST(evidence_count, 99)
    )::bigint AS relevance_score,
    evidence_count,
    failing_evidence_count,
    latest_observed_at,
    is_stale,
    count(*) OVER ()::bigint AS total_matched
FROM ranked_controls
ORDER BY relevance_score DESC, latest_observed_at DESC NULLS LAST, bundle_id ASC, id ASC
LIMIT $2
`

type ListActiveControlsForPortfolioParams struct {
	TenantID     pgtype.UUID   `json:"tenant_id"`
	Limit        int32         `json:"limit"`
	Family       *string       `json:"family"`
	AnchorIds    []pgtype.UUID `json:"anchor_ids"`
	UnboundKinds []string      `json:"unbound_kinds"`
}

type ListActiveControlsForPortfolioRow struct {
	ID                   pgtype.UUID        `json:"id"`
	ScfAnchorID          pgtype.UUID        `json:"scf_anchor_id"`
	Title                string             `json:"title"`
	ControlFamily        string             `json:"control_family"`
	RelevanceScore       int64              `json:"relevance_score"`
	EvidenceCount        int64              `json:"evidence_count"`
	FailingEvidenceCount int64              `json:"failing_evidence_count"`
	LatestObservedAt     pgtype.Timestamptz `json:"latest_observed_at"`
	IsStale              bool               `json:"is_stale"`
	TotalMatched         int64              `json:"total_matched"`
}

// Slice 750 — portfolio / multi-control evidence-summary control-set resolver.
//
// Returns the ACTIVE (non-superseded) controls in the caller's tenant that match
// an OPTIONAL filter, ordered deterministically and capped at $limit (the
// controls-per-summary bound — the headline P0-750-2 leg). The summary is over
// this bounded control set, never the full catalog.
//
// Filter modes (any ONE of the three AC-1 dimensions, all OPTIONAL via
// sqlc.narg so a single query serves every filter the handler accepts; a request
// with no filter is the whole-program rollup):
//
//   - control-family: control_family = sqlc.narg('family')
//   - framework:      scf_anchor_id = ANY(sqlc.narg('anchor_ids')) — the handler
//     resolves a framework_version_id to its SCF anchors via the
//     existing UCF traversal (ListSCFAnchorsForVersion) and passes
//     the anchor-id array here; this reuses the existing
//     framework->anchor->control path rather than inventing a new
//     control-by-framework mechanism.
//     (scope-cell intersection — applicability_expr ∩ framework_scope.predicate —
//     is heavier graph work; deferred to a documented follow-on, not built here.)
//
// A NULL narg disables that filter clause, so the three modes compose to "AND
// of the supplied filters"; in v1 the handler supplies at most one.
//
// Ordering is a deterministic relevance ranking (slice OPENENGINE-407): controls
// with no live evidence first, then controls with failing evidence, then stale
// freshness read-model rows, then stronger evidence coverage and freshest
// observation. bundle_id/id remain the final tie-breakers so the
// controls-per-summary cap selects a reproducible subset, not a random one.
//
// RLS posture: the WHERE tenant_id = $1 clause is belt-and-suspenders alongside
// the GUC-driven RLS policy (slice 002); tenancy.ApplyTenant upstream pins the
// GUC so the read is tenant-scoped (invariant #6).
// #2817: plus the tenant's unbound records of a kind in unbound_kinds that
// the control's evidence_queries declare (internal/evidence/unbound).
func (q *Queries) ListActiveControlsForPortfolio(ctx context.Context, arg ListActiveControlsForPortfolioParams) ([]ListActiveControlsForPortfolioRow, error) {
	rows, err := q.db.Query(ctx, listActiveControlsForPortfolio,
		arg.TenantID,
		arg.Limit,
		arg.Family,
		arg.AnchorIds,
		arg.UnboundKinds,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListActiveControlsForPortfolioRow
	for rows.Next() {
		var i ListActiveControlsForPortfolioRow
		if err := rows.Scan(
			&i.ID,
			&i.ScfAnchorID,
			&i.Title,
			&i.ControlFamily,
			&i.RelevanceScore,
			&i.EvidenceCount,
			&i.FailingEvidenceCount,
			&i.LatestObservedAt,
			&i.IsStale,
			&i.TotalMatched,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

